namespace MouseClicker;

internal static partial class HelpContent
{
    private static HelpPage EuropeanPage(HelpTopic topic, string title, string summary, params HelpSection[] sections) =>
        new(topic, title, summary, Array.AsReadOnly(sections));

    private static partial void AddOtherLanguages(Dictionary<string, HelpCatalog> catalogs)
    {
        catalogs["fr-FR"] = new("Guide d’utilisation", "Rubriques", "Rechercher dans le guide…", "Aucune rubrique trouvée. Essayez un autre mot.", "Fermer", "Guide du clic conditionnel", Array.AsReadOnly(new[]
        {
            EuropeanPage(HelpTopic.QuickStart, "Premiers pas", "Gardez ce guide ouvert à côté du programme pour suivre les étapes.",
                new("Votre premier clic", "1. Cliquez sur Ajouter, tracez la zone où cliquer et donnez-lui un nom.\n2. Réglez l’intervalle en millisecondes et choisissez la séquence.\n3. Cliquez sur Démarrer les clics. Utilisez Arrêter ou ESC pour terminer."),
                new("Cliquer lorsqu’une image apparaît", "Ajoutez d’abord la zone à cliquer, puis ouvrez Modifier la condition avec le menu contextuel ou un double-clic. La rubrique de configuration visuelle explique comment définir séparément la détection et la destination du clic. Le guide ne bloque pas la fenêtre principale.")),
            EuropeanPage(HelpTopic.AreasAndButtons, "Zones et boutons de souris", "Choisissez où cliquer et avec quel bouton.",
                new("Gérer les zones", "Ajouter ouvre une sélection rectangulaire sur le bureau. Nommez chaque zone. Sélectionnez une entrée pour la supprimer ou la déplacer vers le haut ou le bas. Cliquez à nouveau sur l’entrée sélectionnée pour la désélectionner. Le clic se fait à une position aléatoire dans le rectangle."),
                new("Boutons et repères", "Le menu contextuel permet de choisir le bouton gauche [L] ou droit [R]. Si les contours sont affichés, le bleu repère la zone survolée ou sélectionnée et le vert la zone actuellement cliquée. Les contours sont masqués pendant les sessions avec reconnaissance pour ne pas modifier l’image détectée. Les zones peuvent se trouver sur différents écrans.")),
            EuropeanPage(HelpTopic.TimingAndOrder, "Intervalle et ordre", "Le rythme des clics et celui de la détection sont indépendants.",
                new("Intervalle et variation", "L’intervalle global est exprimé en ms. La variation ajoute ou retire une durée aléatoire. Si la somme est négative, sa valeur absolue est utilisée, avec un minimum de 10 ms. Une forte variation peut donc augmenter l’attente moyenne."),
                new("Séquences", "Boucle parcourt la liste puis recommence. Aléatoire choisit une entrée avant de l’exécuter. Une fois parcourt la liste une seule fois. Une entrée conditionnelle attend que son image corresponde avant de cliquer et de passer à la suivante ; elle n’est pas ignorée. En mode aléatoire, le programme attend l’entrée déjà choisie.")),
            EuropeanPage(HelpTopic.ImageConditionSetup, "Configurer un clic conditionnel", "Exemple : détecter une icône Terminé en haut à gauche et cliquer sur Suivant en bas à droite.",
                new("Trois éléments distincts", "La zone de clic indique où agir. La zone de détection indique où chercher. Le modèle est la petite image à retrouver. Ces éléments sont indépendants : les deux zones peuvent être éloignées ou sur des écrans différents. Gardez le guide ouvert à côté de l’application. Pendant la capture ou le test, il devient temporairement transparent puis revient. Pendant la session, placez le programme et le guide hors de la zone de détection."),
                new("Les huit étapes", "1. Ajoutez et nommez la zone à cliquer sur Suivant.\n2. Faites un clic droit sur l’entrée puis Modifier la condition, ou double-cliquez.\n3. Activez la condition visuelle.\n4. Sélectionnez la zone de détection autour de l’emplacement prévu de l’icône.\n5. Capturez une petite image distinctive ou importez un PNG, JPG ou BMP. Le modèle doit tenir dans la zone de détection.\n6. Testez la reconnaissance : consultez le score et le cadre vert. Ce test ne clique pas.\n7. Enregistrez la condition et revenez à la fenêtre principale.\n8. Démarrez les clics. Faites apparaître l’icône ; ESC arrête la session. Une image importée peut servir à attendre une cible qui n’est pas encore visible.")),
            EuropeanPage(HelpTopic.ImageConditionParameters, "Comprendre les paramètres visuels", "Commencez avec les valeurs proposées, puis vérifiez avec le test.",
                new("Score et fréquence", "Le seuil initial est 0,90 : ce score n’est pas une probabilité. Comparez les résultats sur une vraie cible et sur un fond sans cible avant de l’ajuster. La vérification se fait par défaut toutes les 200 ms, indépendamment de l’intervalle global entre clics. Deux images successives doivent correspondre."),
                new("Déclenchement et attente", "Une fois par apparition clique une seule fois tant que l’image reste présente. Deux vérifications successives sans correspondance réarment la condition. Une cible déjà visible au démarrage peut déclencher le premier clic. Répéter tant que visible reste soumis à la séquence et à l’intervalle global. L’attente maximale initiale est de 60 s ; 0 signifie illimitée. Le dépassement arrête toute la session. Le délai obligatoire entre clics n’est pas compté dans cette attente.")),
            EuropeanPage(HelpTopic.ImageConditionTroubleshooting, "Résoudre les problèmes de reconnaissance", "Testez sans clic avant de relancer la session.",
                new("Aucune correspondance ou image refusée", "Capturez ou importez un modèle si aucun n’a été choisi. Il doit être inférieur à la zone de détection, respecter les limites affichées et contenir des détails ; une image unie convient mal. La reconnaissance lit seulement le bureau visible : déplacez les fenêtres qui cachent la cible et restaurez la fenêtre cible si elle est réduite. Après un changement de zoom, de DPI ou de thème, capturez de nouveau le modèle."),
                new("Faux positifs, attente ou lenteur", "Augmentez le seuil ou choisissez un modèle plus distinctif en cas de faux positif. Si l’image reste visible mais qu’un seul clic se produit, vérifiez le mode Une fois par apparition ; choisissez Répéter pour des clics répétés. La séquence peut encore attendre une entrée précédente. Un dépassement du délai arrête la session. Réduisez la zone de détection pour alléger le traitement ; une apparition plus courte que l’intervalle de détection peut être manquée.")),
            EuropeanPage(HelpTopic.HotkeysAndConfiguration, "Raccourcis et configurations", "Conservez vos réglages et gardez une commande d’arrêt accessible.",
                new("Démarrer et arrêter", "F6 est le raccourci initial ; ESC arrête les clics en cours. Fichier → Paramètres des raccourcis accepte F6–F12, Insert, Home, End, PageUp, PageDown et Pause sans Ctrl, Alt, Shift ni Win. Ces préférences sont propres à l’utilisateur Windows, séparées du fichier JSON."),
                new("Enregistrer et charger", "Arrêtez la session avant de modifier ou charger une configuration. Fichier permet d’enregistrer les zones, boutons, délais, séquence et conditions dans un JSON. Les modèles y sont intégrés : aucun chemin externe à maintenir. Les anciens fichiers sans condition restent des clics ordinaires. Le mode SendInput génère des événements logiciels, pas un véritable périphérique matériel."))
        }));

        catalogs["de-DE"] = new("Bedienungsanleitung", "Themen", "Anleitung durchsuchen…", "Keine Themen gefunden. Versuchen Sie einen anderen Suchbegriff.", "Schließen", "Anleitung für Bildbedingungen", Array.AsReadOnly(new[]
        {
            EuropeanPage(HelpTopic.QuickStart, "Erste Schritte", "Lassen Sie diese Anleitung neben dem Programm geöffnet und arbeiten Sie die Schritte ab.",
                new("Der erste Klick", "1. Klicken Sie auf Hinzufügen, ziehen Sie den Klickbereich auf und benennen Sie ihn.\n2. Stellen Sie das Intervall in Millisekunden und die Reihenfolge ein.\n3. Starten Sie die Klicks. Mit Stopp oder ESC beenden Sie den Vorgang."),
                new("Auf ein Bild warten", "Legen Sie zuerst den Klickbereich an. Öffnen Sie dann Bedingung bearbeiten per Rechtsklick oder Doppelklick. Die Bildanleitung erklärt die getrennte Wahl von Suchbereich, Vorlage und Klickziel. Das Hilfefenster blockiert das Hauptfenster nicht.")),
            EuropeanPage(HelpTopic.AreasAndButtons, "Bereiche und Maustasten", "Bestimmen Sie das Klickziel und die zu verwendende Taste.",
                new("Bereiche verwalten", "Hinzufügen öffnet die Rechteckauswahl auf dem Desktop. Benennen Sie die Bereiche; entfernen oder verschieben Sie einen ausgewählten Eintrag mit den entsprechenden Schaltflächen. Ein erneuter Klick auf den ausgewählten Eintrag hebt die Auswahl auf. Die Klickposition wird zufällig innerhalb des Rechtecks gewählt."),
                new("Tasten und Markierungen", "Im Kontextmenü wählen Sie die linke [L] oder rechte [R] Maustaste. Bei eingeschalteten Rahmen markiert Blau den ausgewählten oder mit der Maus berührten Bereich, Grün den gerade angeklickten. Bei Bildbedingungen bleiben die Rahmen verborgen, damit sie die Erkennung nicht beeinflussen. Bereiche dürfen auf verschiedenen Monitoren liegen.")),
            EuropeanPage(HelpTopic.TimingAndOrder, "Zeitabstände und Reihenfolge", "Klickintervall und Prüfintervall sind unterschiedliche Einstellungen.",
                new("Intervall und Streuung", "Das globale Intervall wird in ms angegeben. Die Streuung addiert oder subtrahiert einen zufälligen Zeitwert. Eine negative Summe wird als Absolutwert verwendet; mindestens 10 ms bleiben erhalten. Große Streuung kann die mittlere Wartezeit erhöhen."),
                new("Ablauf", "Schleife durchläuft die Liste wiederholt. Zufällig wählt zunächst einen Eintrag. Einmal führt die Liste einmal aus. Bei einer Bildbedingung wartet der aktuelle Eintrag auf eine Übereinstimmung und klickt erst dann; er wird nicht übersprungen. Im Zufallsmodus wird auf den bereits ausgewählten Eintrag gewartet.")),
            EuropeanPage(HelpTopic.ImageConditionSetup, "Bildbedingung Schritt für Schritt", "Beispiel: links oben ein Fertig-Symbol erkennen und rechts unten auf Weiter klicken.",
                new("Drei getrennte Angaben", "Klickbereich bedeutet: Wo wird geklickt? Suchbereich bedeutet: Wo wird gesucht? Die Vorlage bestimmt: Welches Bild wird gesucht? Die Bereiche sind unabhängig und dürfen auf verschiedenen Monitoren liegen. Stellen Sie die Anleitung zum Mitlesen neben das Programm. Bei Aufnahme oder Test wird sie kurz transparent und danach wiederhergestellt. Während der Ausführung dürfen Programm und Anleitung den Suchbereich nicht verdecken."),
                new("Acht Schritte", "1. Legen Sie den Klickbereich über Weiter an und benennen Sie ihn.\n2. Öffnen Sie per Rechtsklick Bedingung bearbeiten oder per Doppelklick die Einstellungen.\n3. Aktivieren Sie die Bildbedingung.\n4. Wählen Sie den Suchbereich um die erwartete Position des Symbols.\n5. Nehmen Sie eine kleine, markante Vorlage auf oder importieren Sie PNG, JPG oder BMP. Die Vorlage muss in den Suchbereich passen.\n6. Testen Sie die Erkennung und prüfen Sie Wert und grünen Trefferrahmen. Dabei wird nicht geklickt.\n7. Speichern Sie die Bedingung und kehren Sie zum Hauptfenster zurück.\n8. Starten Sie die Klicks und lassen Sie das Symbol erscheinen. ESC stoppt. Eine importierte Vorlage darf auf ein Bild warten, das momentan noch nicht sichtbar ist.")),
            EuropeanPage(HelpTopic.ImageConditionParameters, "Bildparameter verstehen", "Beginnen Sie mit den Vorgaben und passen Sie sie anhand des Erkennungstests an.",
                new("Schwelle und Prüftakt", "Die Standardschwelle beträgt 0,90. Der Wert ist keine Wahrscheinlichkeit. Testen Sie Zielbild und Hintergrund ohne Ziel vor einer Änderung. Das Prüfintervall beträgt zunächst 200 ms und ist vom globalen Klickintervall unabhängig. Zwei aufeinanderfolgende Prüfungen müssen übereinstimmen."),
                new("Auslösung und Zeitlimit", "Einmal pro Erscheinen klickt bei einem dauerhaft sichtbaren Bild nur einmal. Zwei aufeinanderfolgende Prüfungen ohne Treffer geben die Auslösung wieder frei. Ein beim Start bereits sichtbares Ziel kann den ersten Klick auslösen. Wiederholen solange sichtbar beachtet weiterhin Reihenfolge und Klickintervall. Das Zeitlimit ist zunächst 60 s, mit 0 unbegrenzt. Bei Überschreitung stoppt die gesamte Sitzung. Die vorgeschriebene Pause zwischen Klicks zählt nicht als Wartezeit für die Bedingung.")),
            EuropeanPage(HelpTopic.ImageConditionTroubleshooting, "Erkennungsprobleme beheben", "Prüfen Sie die Erkennung ohne Klick, bevor Sie den Ablauf erneut starten.",
                new("Kein Treffer oder ungültige Vorlage", "Nehmen Sie zuerst eine Vorlage auf oder importieren Sie ein Bild. Sie muss in den Suchbereich passen, die angezeigten Grenzen einhalten und erkennbare Details enthalten; eine einfarbige Fläche ist ungeeignet. Nur der sichtbare Desktop wird geprüft. Verschieben Sie verdeckende Fenster und stellen Sie minimierte Zielfenster wieder her. Nach Änderungen an Zoom, DPI oder Design sollten Sie die Vorlage neu aufnehmen."),
                new("Falsche Treffer, Warten oder hohe Last", "Bei falschen Treffern erhöhen Sie die Schwelle oder verwenden eine markantere Vorlage. Ein dauerhaftes Bild erzeugt im Modus Einmal pro Erscheinen keinen zweiten Klick; wählen Sie bei Bedarf Wiederholen. Möglicherweise wartet der Ablauf noch auf den vorherigen Eintrag. Ein Zeitlimit stoppt die gesamte Sitzung. Ein kleinerer Suchbereich senkt den Aufwand. Kürzere Bildwechsel als das Prüfintervall können unbemerkt bleiben.")),
            EuropeanPage(HelpTopic.HotkeysAndConfiguration, "Tastenkürzel und Konfigurationen", "Speichern Sie Einstellungen und behalten Sie eine schnelle Stoppmöglichkeit.",
                new("Start und Stopp", "Standardmäßig startet und stoppt F6; ESC beendet laufende Klicks. Unter Datei → Tastenkürzel sind F6–F12, Insert, Home, End, PageUp, PageDown und Pause ohne Ctrl, Alt, Shift oder Win möglich. Diese benutzerspezifischen Einstellungen werden getrennt vom JSON gespeichert."),
                new("Speichern und Laden", "Stoppen Sie vor dem Bearbeiten oder Laden einer Konfiguration. Datei speichert Bereiche, Maustasten, Zeiten, Reihenfolge und Bedingungen als JSON. Vorlagen werden eingebettet und benötigen keinen externen Dateipfad. Alte Dateien ohne Bildbedingungen führen weiterhin normale Klicks aus. SendInput erzeugt Software-Eingaben und stellt keine echte Hardware dar."))
        }));

        catalogs["es-ES"] = new("Guía de uso", "Temas", "Buscar en la guía…", "No hay temas coincidentes. Pruebe otra palabra.", "Cerrar", "Guía de clic por imagen", Array.AsReadOnly(new[]
        {
            EuropeanPage(HelpTopic.QuickStart, "Primeros pasos", "Mantenga esta guía al lado del programa mientras realiza los pasos.",
                new("Su primer clic", "1. Pulse Añadir, dibuje la zona de clic y asígnele un nombre.\n2. Ajuste el intervalo en milisegundos y la secuencia.\n3. Inicie los clics. Para terminar, pulse Detener o ESC."),
                new("Esperar una imagen", "Primero añada la zona de clic. Abra Editar condición con el botón derecho o con doble clic. La guía de imágenes explica cómo separar el destino, el área de búsqueda y la plantilla. Puede operar la ventana principal sin cerrar la ayuda.")),
            EuropeanPage(HelpTopic.AreasAndButtons, "Zonas y botones del ratón", "Elija dónde actuar y con qué botón.",
                new("Organizar zonas", "Añadir permite dibujar un rectángulo en el escritorio. Nombre cada zona; seleccione una entrada para eliminarla o subirla y bajarla. Volver a pulsar una entrada seleccionada quita la selección. Cada clic elige una posición aleatoria dentro del rectángulo."),
                new("Botones y colores", "El menú contextual permite elegir el botón izquierdo [L] o derecho [R]. Con los marcos activados, el azul indica la zona seleccionada o señalada y el verde la que recibe el clic actual. Durante las sesiones con reconocimiento se ocultan los marcos para no alterar la imagen. Las zonas pueden estar en monitores distintos.")),
            EuropeanPage(HelpTopic.TimingAndOrder, "Intervalos y orden", "El intervalo de clic y el de detección son independientes.",
                new("Intervalo y variación", "El intervalo global se expresa en ms. La variación suma o resta un tiempo aleatorio. Si el total es negativo, se utiliza su valor absoluto, siempre con un mínimo de 10 ms. Una variación grande puede aumentar la espera media."),
                new("Secuencias", "Bucle repite la lista. Aleatorio elige primero una entrada. Una vez recorre la lista una sola vez. Una entrada condicional espera su imagen antes de hacer clic y avanzar; no se omite. En modo aleatorio se espera la entrada ya elegida, sin escoger otra mientras no coincida.")),
            EuropeanPage(HelpTopic.ImageConditionSetup, "Configurar la condición visual", "Ejemplo: detectar un icono Listo arriba a la izquierda y pulsar Siguiente abajo a la derecha.",
                new("Tres elementos independientes", "La zona de clic indica dónde pulsar; la zona de detección indica dónde buscar; la plantilla indica qué imagen buscar. Las dos zonas pueden estar separadas e incluso en monitores distintos. Deje la guía abierta al lado del programa. Durante la captura o prueba se vuelve transparente temporalmente y después se restaura. Durante la sesión, coloque el programa y la ayuda fuera de la zona de detección."),
                new("Ocho pasos", "1. Añada y nombre la zona de clic sobre Siguiente.\n2. Abra Editar condición con el botón derecho sobre la entrada o haga doble clic.\n3. Active la condición visual.\n4. Seleccione el área donde debe aparecer el icono.\n5. Capture una plantilla pequeña y distintiva o importe PNG, JPG o BMP. Debe caber dentro de la zona de detección.\n6. Pruebe el reconocimiento y consulte la puntuación y el marco verde. La prueba no hace clic.\n7. Guarde la condición y vuelva a la ventana principal.\n8. Inicie los clics y haga aparecer el icono. ESC detiene la sesión. Puede importar una imagen para esperar un objetivo que todavía no esté visible.")),
            EuropeanPage(HelpTopic.ImageConditionParameters, "Parámetros de reconocimiento", "Empiece con los valores predeterminados y ajústelos usando la prueba.",
                new("Umbral y frecuencia", "El umbral inicial es 0,90; la puntuación no es una probabilidad. Pruebe tanto el objetivo real como un fondo sin objetivo antes de ajustarlo. La detección se comprueba cada 200 ms por defecto, independientemente del intervalo global entre clics. Se necesitan dos coincidencias consecutivas."),
                new("Activación y espera", "Una vez por aparición pulsa solo una vez mientras la imagen siga presente. Dos comprobaciones consecutivas sin coincidencia permiten volver a activar. Una imagen ya visible al iniciar puede producir el primer clic. Repetir mientras visible sigue respetando la secuencia y el intervalo de clic. El límite inicial es 60 s; 0 espera sin límite. Al vencer se detiene toda la sesión. El descanso obligatorio entre clics no cuenta como espera de la condición.")),
            EuropeanPage(HelpTopic.ImageConditionTroubleshooting, "Resolver problemas visuales", "Pruebe el reconocimiento sin clics antes de reiniciar.",
                new("No reconoce o rechaza la imagen", "Capture o importe una plantilla si falta. Debe caber en la zona de detección, respetar los límites indicados y contener detalles; evite superficies de un solo color. Solo se reconoce el escritorio visible: retire las ventanas que tapen el objetivo y restaure las minimizadas. Si cambia el zoom, DPI o tema, vuelva a capturar la plantilla."),
                new("Falsos positivos, espera o lentitud", "Suba el umbral o elija una plantilla más distintiva si hay falsos positivos. Una imagen permanente no produce otro clic en Una vez por aparición; elija Repetir si necesita varios. La secuencia puede seguir esperando una entrada anterior. Un tiempo agotado detiene toda la sesión. Reduzca la zona de detección para bajar el coste. Las apariciones más breves que el intervalo de detección pueden pasar inadvertidas.")),
            EuropeanPage(HelpTopic.HotkeysAndConfiguration, "Atajos y configuraciones", "Guarde sus ajustes y conserve una forma rápida de detener los clics.",
                new("Iniciar y detener", "F6 es el atajo inicial y ESC detiene los clics activos. En Archivo → Atajos se admiten F6–F12, Insert, Home, End, PageUp, PageDown y Pause sin Ctrl, Alt, Shift ni Win. Los atajos se guardan por usuario de Windows, separados del JSON."),
                new("Guardar y cargar", "Detenga la sesión antes de editar o cargar. Archivo guarda zonas, botones, tiempos, secuencia y condiciones en JSON. Las plantillas quedan integradas, sin depender de una ruta externa. Las configuraciones antiguas sin condiciones mantienen los clics normales. SendInput genera entradas de software, no convierte los eventos en hardware real."))
        }));

        catalogs["ru-RU"] = new("Руководство", "Разделы", "Поиск по руководству…", "Разделы не найдены. Попробуйте другое слово.", "Закрыть", "Руководство по условным кликам", Array.AsReadOnly(new[]
        {
            EuropeanPage(HelpTopic.QuickStart, "Начало работы", "Оставьте руководство рядом с программой и выполняйте шаги, не закрывая его.",
                new("Первый клик", "1. Нажмите Добавить, выделите область клика и задайте имя.\n2. Укажите интервал в миллисекундах и порядок выполнения.\n3. Запустите клики. Для завершения нажмите Стоп или ESC."),
                new("Ожидание изображения", "Сначала добавьте область клика. Затем откройте Редактировать условие правой кнопкой или двойным щелчком. Раздел настройки распознавания объясняет раздельный выбор цели клика, области поиска и шаблона. Окно справки не блокирует основную программу.")),
            EuropeanPage(HelpTopic.AreasAndButtons, "Области и кнопки мыши", "Выберите место клика и нужную кнопку.",
                new("Управление списком", "Добавить открывает выделение прямоугольника на рабочем столе. Задайте имя каждой области. Выбранную запись можно удалить, поднять или опустить. Повторный щелчок по выбранной записи снимает выделение. Точка клика выбирается случайно внутри прямоугольника."),
                new("Кнопки и подсветка", "Контекстное меню выбирает левую [L] или правую [R] кнопку. При включённых рамках синий цвет показывает выбранную область или область под указателем в списке, зелёный — текущий клик. В сеансах с распознаванием рамки скрываются, чтобы не менять изображение. Области могут находиться на разных мониторах.")),
            EuropeanPage(HelpTopic.TimingAndOrder, "Интервалы и порядок", "Интервал кликов и частота распознавания задаются отдельно.",
                new("Интервал и разброс", "Общий интервал измеряется в мс. Разброс прибавляет или вычитает случайную задержку. Если сумма отрицательна, берётся её модуль; минимальная задержка — 10 мс. Большой разброс может увеличить среднее ожидание."),
                new("Последовательности", "Цикл повторяет список, Случайно сначала выбирает запись, Один раз проходит список однократно. Условная запись ждёт совпадения изображения, затем кликает и переходит дальше; она не пропускается. В случайном режиме ожидается уже выбранная запись, без повторного выбора до совпадения.")),
            EuropeanPage(HelpTopic.ImageConditionSetup, "Настройка распознавания", "Пример: значок Готово появляется слева вверху, а клик нужен по Далее справа внизу.",
                new("Три независимых элемента", "Область клика определяет, куда нажать. Область обнаружения — где искать. Шаблон — какое изображение искать. Области могут быть разнесены и даже находиться на разных мониторах. Руководство можно держать открытым рядом. При снимке или проверке оно временно становится прозрачным, затем восстанавливается. Во время сеанса разместите программу и справку вне области обнаружения."),
                new("Восемь шагов", "1. Добавьте и назовите область клика на кнопке Далее.\n2. Откройте Редактировать условие через правую кнопку по записи или двойной щелчок.\n3. Включите визуальное условие.\n4. Выделите область, где ожидается значок.\n5. Снимите небольшой характерный шаблон или импортируйте PNG, JPG либо BMP. Шаблон должен помещаться в область обнаружения.\n6. Проверьте распознавание: посмотрите оценку и зелёную рамку совпадения. Проверка не нажимает мышь.\n7. Сохраните условие и вернитесь в основное окно.\n8. Запустите клики и дождитесь значка. ESC останавливает сеанс. Можно импортировать образец цели, которой пока нет на экране.")),
            EuropeanPage(HelpTopic.ImageConditionParameters, "Параметры распознавания", "Начните со стандартных значений и настройте их по результатам проверки.",
                new("Порог и частота", "Начальный порог — 0,90. Оценка не является вероятностью. Перед изменением сравните настоящую цель и фон без цели в режиме проверки. Интервал обнаружения по умолчанию 200 мс не зависит от общего интервала кликов. Нужны два последовательных совпадения."),
                new("Срабатывание и тайм-аут", "Один раз при появлении кликает только один раз, пока картинка остаётся видимой. Две последовательные проверки без совпадения разрешают новое срабатывание. Уже видимая при запуске цель может вызвать первый клик. Повторять пока видно учитывает общий интервал и порядок. Начальный тайм-аут — 60 с, 0 означает неограниченное ожидание. По истечении времени останавливается весь сеанс. Обязательная пауза между кликами не входит в ожидание условия.")),
            EuropeanPage(HelpTopic.ImageConditionTroubleshooting, "Проблемы распознавания", "Перед повторным запуском используйте проверку без кликов.",
                new("Нет совпадения или неверный шаблон", "Если шаблон не выбран, снимите или импортируйте его. Он должен помещаться в область обнаружения, соблюдать указанные ограничения и содержать детали; однотонная картинка не подходит. Анализируется только видимый рабочий стол: уберите перекрывающие окна и восстановите свёрнутое целевое окно. После изменения масштаба, DPI или темы снимите шаблон заново."),
                new("Ложные совпадения, ожидание и нагрузка", "При ложных совпадениях повысьте порог или выберите более характерный образец. Постоянно видимая цель не повторяет клик в режиме Один раз при появлении; для повторения смените режим. Список может ещё ждать предыдущую запись. Истечение тайм-аута останавливает весь сеанс. Уменьшите область поиска для снижения нагрузки. Изображение, исчезающее быстрее интервала проверки, может быть пропущено.")),
            EuropeanPage(HelpTopic.HotkeysAndConfiguration, "Клавиши и конфигурации", "Сохраняйте настройки и держите под рукой быструю остановку.",
                new("Запуск и остановка", "Исходная клавиша — F6, ESC останавливает текущие клики. Файл → Горячие клавиши принимает F6–F12, Insert, Home, End, PageUp, PageDown и Pause без Ctrl, Alt, Shift или Win. Эти настройки пользователя Windows хранятся отдельно от JSON."),
                new("Сохранение и загрузка", "Остановите сеанс перед редактированием или загрузкой. Через Файл сохраняются области, кнопки, времена, порядок и условия в JSON. Шаблоны встроены в файл и не требуют внешних путей. Старые файлы без условий продолжают выполнять обычные клики. SendInput создаёт программные события, а не настоящее аппаратное устройство."))
        }));

        catalogs["pt-BR"] = new("Guia de uso", "Tópicos", "Pesquisar no guia…", "Nenhum tópico encontrado. Tente outra palavra.", "Fechar", "Guia de clique por imagem", Array.AsReadOnly(new[]
        {
            EuropeanPage(HelpTopic.QuickStart, "Primeiros passos", "Deixe este guia ao lado do programa e siga as etapas sem fechá-lo.",
                new("Seu primeiro clique", "1. Clique em Adicionar, marque a área do clique e dê um nome.\n2. Ajuste o intervalo em milissegundos e a sequência.\n3. Inicie os cliques. Para encerrar, use Parar ou ESC."),
                new("Esperar uma imagem", "Primeiro adicione a área do clique. Abra Editar condição com o botão direito ou um clique duplo. A configuração visual explica como separar destino, área de busca e modelo. A janela de ajuda não bloqueia a janela principal.")),
            EuropeanPage(HelpTopic.AreasAndButtons, "Áreas e botões do mouse", "Escolha onde clicar e qual botão usar.",
                new("Organizar áreas", "Adicionar abre a seleção de um retângulo no desktop. Nomeie cada área; selecione uma entrada para removê-la, subir ou descer na lista. Clicar novamente na entrada selecionada limpa a seleção. Cada clique escolhe um ponto aleatório dentro do retângulo."),
                new("Botões e destaques", "O menu de contexto escolhe o botão esquerdo [L] ou direito [R]. Com as bordas ativadas, azul indica a área selecionada ou apontada na lista e verde indica o clique atual. Durante sessões com reconhecimento, as bordas ficam ocultas para não alterar a imagem. As áreas podem ficar em monitores diferentes.")),
            EuropeanPage(HelpTopic.TimingAndOrder, "Intervalos e sequência", "O intervalo de clique e o de detecção são independentes.",
                new("Intervalo e variação", "O intervalo global usa ms. A variação soma ou subtrai um tempo aleatório. Se o total for negativo, usa-se o valor absoluto, mantendo um mínimo de 10 ms. Uma variação grande pode aumentar a espera média."),
                new("Modos de execução", "Loop repete a lista. Aleatório escolhe primeiro uma entrada. Uma vez percorre a lista apenas uma vez. Uma entrada condicional espera a imagem antes de clicar e avançar; não é ignorada. No modo aleatório, o programa espera a entrada já escolhida em vez de sortear outra enquanto não houver correspondência.")),
            EuropeanPage(HelpTopic.ImageConditionSetup, "Configurar uma condição visual", "Exemplo: detectar o ícone Concluído no alto à esquerda e clicar em Avançar embaixo à direita.",
                new("Três elementos separados", "A área de clique diz onde agir; a área de detecção diz onde procurar; o modelo diz qual imagem procurar. As áreas são independentes e podem ficar distantes ou em monitores diferentes. Mantenha o guia aberto ao lado do aplicativo. Durante a captura ou o teste, ele fica temporariamente transparente e depois volta. Durante a sessão, deixe o programa e o guia fora da área de detecção."),
                new("Oito etapas", "1. Adicione e nomeie a área de clique sobre Avançar.\n2. Abra Editar condição pelo botão direito na entrada ou por clique duplo.\n3. Ative a condição visual.\n4. Selecione a área onde o ícone deve aparecer.\n5. Capture um modelo pequeno e distinto ou importe PNG, JPG ou BMP. O modelo precisa caber na área de detecção.\n6. Teste o reconhecimento e observe a pontuação e a borda verde. O teste não clica.\n7. Salve a condição e volte à janela principal.\n8. Inicie os cliques e faça o ícone aparecer. ESC interrompe a sessão. Um modelo importado pode aguardar uma imagem que ainda não esteja visível.")),
            EuropeanPage(HelpTopic.ImageConditionParameters, "Entender os parâmetros visuais", "Comece pelos valores sugeridos e ajuste usando o teste de reconhecimento.",
                new("Limiar e frequência", "O limiar inicial é 0,90; a pontuação não é uma probabilidade. Teste o alvo real e um fundo sem alvo antes de ajustar. A detecção ocorre a cada 200 ms por padrão, separada do intervalo global entre cliques. São necessárias duas correspondências consecutivas."),
                new("Acionamento e tempo limite", "Uma vez por aparição clica apenas uma vez enquanto a imagem continua presente. Duas verificações consecutivas sem correspondência liberam um novo acionamento. Um alvo já visível ao iniciar pode disparar o primeiro clique. Repetir enquanto visível continua respeitando a sequência e o intervalo global. O tempo limite inicial é 60 s; 0 espera sem limite. Ao vencer, toda a sessão para. A pausa obrigatória entre cliques não conta como espera da condição.")),
            EuropeanPage(HelpTopic.ImageConditionTroubleshooting, "Resolver problemas de reconhecimento", "Use o teste sem cliques antes de reiniciar a execução.",
                new("Sem correspondência ou modelo inválido", "Capture ou importe um modelo caso ainda não tenha escolhido um. Ele deve caber na área de detecção, respeitar os limites exibidos e conter detalhes; uma superfície de cor única é inadequada. Somente o desktop visível é analisado: afaste janelas que cubram o alvo e restaure a janela alvo se estiver minimizada. Após mudar zoom, DPI ou tema, capture o modelo novamente."),
                new("Falsos positivos, espera ou lentidão", "Aumente o limiar ou escolha um modelo mais distinto se houver falsos positivos. Uma imagem permanente não repete o clique em Uma vez por aparição; escolha Repetir quando necessário. A sequência pode estar esperando uma entrada anterior. Um tempo limite encerra toda a sessão. Reduza a área de detecção para diminuir o trabalho. Aparições mais breves que o intervalo de verificação podem não ser percebidas.")),
            EuropeanPage(HelpTopic.HotkeysAndConfiguration, "Atalhos e configurações", "Salve os ajustes e mantenha uma forma rápida de parar.",
                new("Iniciar e parar", "F6 é o atalho inicial; ESC para os cliques em execução. Arquivo → Configurações de atalhos aceita F6–F12, Insert, Home, End, PageUp, PageDown e Pause sem Ctrl, Alt, Shift ou Win. Essas preferências do usuário Windows ficam separadas do JSON."),
                new("Salvar e carregar", "Pare a sessão antes de editar ou carregar uma configuração. Arquivo salva áreas, botões, tempos, sequência e condições em JSON. Os modelos ficam embutidos, sem depender de caminhos externos. Arquivos antigos sem condições mantêm os cliques normais. SendInput gera entradas de software e não transforma os eventos em hardware real."))
        }));
